package org.marketreview.nativeapp;
import java.util.*;
import org.json.*;
final class CommentWorkshopModel {
  static final String[] FIELDS={"title","universe","timeframe","signalTiming","entryRule","exitRule","stopRule","positionRule","costRule"};
  static final String[] FIELD_LABELS={"规则名称","股票池","周期","信号时点","入场规则","退出规则","止损规则","仓位规则","费用与滑点"};
  static void require(boolean b,String s){SourceAnalysisPacket.require(b,s);}
  static JSONObject obj(JSONObject o,String k){return SourceAnalysisPacket.object(o,k);}
  static String text(JSONObject o,String k){return text(o,k,"");}
  static String text(JSONObject o,String k,String fallback){require(!o.has(k)||o.isNull(k)||o.opt(k) instanceof String,"评论字段不是文本："+k);return o.optString(k,fallback);}
  static String id(Object v){if(v instanceof String)return (String)v;if(v instanceof Number){try{long n=new java.math.BigDecimal(v.toString()).longValueExact();require(n>=0&&n<=9007199254740991L,"旧来源ID不是安全整数");return Long.toString(n);}catch(ArithmeticException e){throw new IllegalArgumentException("旧来源ID不是安全整数");}}return "";}
  static Object metric(Object v){try{if(v==null||v==JSONObject.NULL||v.equals(""))return JSONObject.NULL;double n=Double.parseDouble(v.toString());return Double.isFinite(n)&&n>=0?n:JSONObject.NULL;}catch(Exception e){return JSONObject.NULL;}}
  static void sorted(SourceAnalysisPacket.JsonText out,Object value) throws Exception {
    if(value instanceof JSONObject){JSONObject o=(JSONObject)value;List<String> keys=new ArrayList<>();Iterator<String> it=o.keys();while(it.hasNext())keys.add(it.next());Collections.sort(keys);out.raw("{");boolean first=true;for(String k:keys){if(!first)out.raw(",");first=false;out.quote(k);out.raw(":");sorted(out,o.get(k));}out.raw("}");}
    else if(value instanceof JSONArray){JSONArray a=(JSONArray)value;out.raw("[");for(int i=0;i<a.length();i++){if(i>0)out.raw(",");sorted(out,a.get(i));}out.raw("]");}
    else if(value instanceof Number)out.raw(new java.math.BigDecimal(value.toString()).stripTrailingZeros().toPlainString());else out.value(value);
  }
  static String canonical(Object value) throws Exception {SourceAnalysisPacket.JsonText out=new SourceAnalysisPacket.JsonText(true);sorted(out,value);return out.out.toString();}
  static String labelId(String observation,String comment) throws Exception {return "evidence:"+SourceAnalysisPacket.hash(observation+'\0'+comment);}
  static String known(String s){return s.isEmpty()?"未记录":s;}
  static String labelName(String v){switch(v){case "support":return "支持";case "counter":return "反证 / 失效反馈";case "question":return "待核问题";default:return "未分类";}}
  static String identityName(String v){switch(v){case "verified":return "主页一致（导入快照）";case "platform_marked":return "平台标注（导入快照）";case "suspected":return "同名待核";case "none":return "一般评论";default:return "身份未记录";}}
  static String readableComment(JSONObject c) throws Exception {
    Map<String,String> identities=new HashMap<>();identities.put("none","一般评论");identities.put("suspected","同名疑似，未作为作者");identities.put("verified","导入快照中主页一致");identities.put("platform_marked","导入快照中平台标注作者");
    StringBuilder out=new StringBuilder("用户："+known(c.optString("authorName"))+" · "+identities.getOrDefault(c.optString("creatorStatus"),"身份未记录")+"\n发布时间："+known(c.optString("publishedAt"))+"\n快照观察时间："+known(c.optString("observedAt"))+"\n赞："+(c.isNull("likes")?"未记录":c.opt("likes"))+"\n作者主页："+known(c.optString("authorProfileUrl"))+"\n评论ID："+c.optString("commentId")+"\n身份仅说明导入快照，未做当前在线核验。\n");
    if(!c.optString("parentCommentId").isEmpty())out.append("\n回复来源（").append(c.optString("parentCommentId")).append("）：").append(c.optBoolean("parentMissing")?"父评论原文未保存，不能补造":c.optString("parentAuthorName")+"\n"+c.optString("parentText")).append('\n');out.append("\n评论完整原文：\n").append(c.optString("text"));JSONArray versions=c.optJSONArray("versions");if(versions!=null)for(int i=0;i<versions.length();i++){JSONObject v=versions.getJSONObject(i);out.append("\n\n历史版本").append(i+1).append(" · ").append(known(v.optString("observedAt"))).append(" · ").append(known(v.optString("authorName"))).append('\n').append(v.optString("text"));}return out.toString();
  }
  static String readableCoverage(JSONObject row) throws Exception {JSONObject c=row.getJSONObject("coverage");return c.optString("message","保存范围未记录，不能断言没有评论")+" · 实际保存"+row.getJSONArray("comments").length()+"条 · 原可见数"+(c.isNull("visibleCount")?"未记录":c.opt("visibleCount"))+" · 原总数"+(c.isNull("total")?"未记录":c.opt("total"))+" · "+(c.optBoolean("complete")?"文件声明此保存范围完整，非在线核验":"保存范围未完整确认，不等于视频无评论");}
  static String profile(String s){String url=SourceAnalysisPacket.publicUrl(s);return url.endsWith("/")?url.substring(0,url.length()-1):url;}
  static JSONObject observation(JSONObject channel,JSONObject item,JSONObject data) throws Exception {
    String channelId=id(channel.opt("id")),observationId=id(item.opt("id")),profile=SourceAnalysisPacket.publicUrl(text(channel,"profileUrl")),url=SourceAnalysisPacket.publicUrl(text(item,"sourceUrl"));
    String channelKey=text(channel,"channelKey"),contentId=text(item,"externalContentId"),externalKey=text(item,"externalKey"),observationKey=!contentId.isEmpty()?contentId:!externalKey.isEmpty()?externalKey:!url.isEmpty()?url:observationId;if(channelKey.isEmpty())channelKey=profile.isEmpty()?channelId:profile;require(!channelKey.isEmpty()&&!observationKey.isEmpty(),"频道或观察记录缺少稳定身份，未导入");
    require(!data.has("comments")||data.optJSONArray("comments")!=null,"评论列表无效");require(!data.has("coverage")||data.isNull("coverage")||data.optJSONObject("coverage")!=null,"评论覆盖范围不是对象");JSONArray comments=data.optJSONArray("comments"),list=new JSONArray();Set<String> ids=new HashSet<>();
    if(comments!=null)for(int i=0;i<comments.length();i++){
      JSONObject raw=comments.getJSONObject(i);String cid=text(raw,"commentId"),body=text(raw,"text");require(!cid.isEmpty()&&!body.trim().isEmpty()&&ids.add(cid),"评论身份/正文为空或身份重复；未静默丢弃");
      String authorProfile=SourceAnalysisPacket.publicUrl(text(raw,"authorProfileUrl")),status="none",method="";
      if(!profile.isEmpty()&&!authorProfile.isEmpty()&&profile(profile).equals(profile(authorProfile))){status="verified";method="profile_url";}
      else if(Boolean.TRUE.equals(raw.opt("isCreatorLabel"))||(text(raw,"creatorStatus").equals("platform_marked")&&text(raw,"verificationMethod").equals("platform_label"))){status="platform_marked";method="platform_label";}
      else if(!text(raw,"authorName").isEmpty()&&text(raw,"authorName").equals(text(channel,"displayName"))){status="suspected";method="display_name";}
      require(!raw.has("versions")||raw.optJSONArray("versions")!=null,"评论历史版本不是列表");JSONArray versions=new JSONArray(),oldVersions=raw.optJSONArray("versions");if(oldVersions!=null)for(int j=0;j<oldVersions.length();j++){JSONObject v=oldVersions.getJSONObject(j);versions.put(new JSONObject().put("text",text(v,"text")).put("observedAt",text(v,"observedAt")).put("authorName",text(v,"authorName")).put("likes",metric(v.opt("likes"))));}
      String parent=text(raw,"parentCommentId");list.put(new JSONObject().put("commentId",cid).put("parentCommentId",parent.isEmpty()?text(raw,"replyToCommentId"):parent).put("authorName",text(raw,"authorName","未知用户")).put("authorProfileUrl",authorProfile).put("authorPlatformId",text(raw,"authorPlatformId"))
        .put("text",body).put("publishedAt",text(raw,"publishedAt")).put("observedAt",text(raw,"observedAt")).put("likes",metric(raw.opt("likes"))).put("creatorStatus",status).put("verificationMethod",method).put("importedCreatorStatus",text(raw,"creatorStatus"))
        .put("visibilityStatus",text(raw,"visibilityStatus","observed")).put("versions",versions).put("identityScope","imported-snapshot-not-live-verification"));
    }
    JSONObject input=obj(data,"coverage");Object total=metric(data.opt("total"));boolean partial=data.optBoolean("hasMore")||(total instanceof Number&&((Number)total).doubleValue()>list.length())||data.optInt("offset")>0;
    JSONObject coverage=new JSONObject().put("status",text(input,"status","not_loaded")).put("message",text(input,"message","保存范围未知，不能据此断言没有评论。")).put("observedAt",text(input,"observedAt")).put("visibleCount",metric(input.opt("visibleCount")))
      .put("declaredComplete",Boolean.TRUE.equals(input.opt("complete"))).put("complete",Boolean.TRUE.equals(input.opt("complete"))&&!partial).put("hasMore",data.optBoolean("hasMore")).put("total",total).put("offset",data.optInt("offset"));
    JSONObject row=new JSONObject().put("kind","observations").put("channelId",channelId).put("channelKey",channelKey).put("channelName",text(channel,"displayName")).put("profileUrl",profile).put("observationId",observationId).put("externalContentId",contentId).put("sourceUrl",url).put("title",text(item,"title","未命名观察记录"))
      .put("publishedAt",text(item,"publishedAt")).put("content",text(item,"content")).put("transcript",text(item,"transcript")).put("evidenceLevel",text(item,"evidenceLevel","unknown")).put("availabilityStatus",text(item,"availabilityStatus","unknown"))
      .put("comments",list).put("coverage",coverage).put("provenance","local-import-unverified");SourceAnalysisPacket.size(row);
    String body=canonical(row),sourceKey="observation:"+SourceAnalysisPacket.hash(channelKey+'\0'+observationKey);return row.put("sourceKey",sourceKey).put("id",sourceKey+":"+SourceAnalysisPacket.hash(body));
  }
  static JSONObject assess(JSONObject raw) throws Exception {JSONArray missing=new JSONArray();for(int i=1;i<FIELDS.length;i++)if(text(raw,FIELDS[i]).trim().isEmpty())missing.put(FIELD_LABELS[i]);return new JSONObject().put("complete",missing.length()==0).put("status",missing.length()==0?"rule_complete_not_validated":"draft").put("missingLabels",missing).put("boundary","规则完整不等于策略有效；不运行回测、不补参数、不生成订单");}
  static JSONObject validate(JSONObject row) throws Exception {
    String kind=row.optString("kind"),id=row.optString("id");require(!id.isEmpty()&&id.length()<=300&&Arrays.asList("observations","rules","labels","bindings","drafts","archives","previews").contains(kind),"工坊记录身份或类型无效");
    if(kind.equals("observations")){require(row.optJSONArray("comments")!=null&&row.optJSONObject("coverage")!=null&&row.opt("content") instanceof String&&row.opt("transcript") instanceof String,"观察记录正文或评论结构无效");JSONArray a=row.getJSONArray("comments");Set<String> ids=new HashSet<>();for(int i=0;i<a.length();i++){JSONObject c=a.getJSONObject(i);String cid=text(c,"commentId"),status=text(c,"creatorStatus"),method=text(c,"verificationMethod");require(!cid.isEmpty()&&!text(c,"text").trim().isEmpty()&&ids.add(cid),"评论正文或复合身份无效");
      require(Arrays.asList("none","suspected","verified","platform_marked").contains(status)&&c.optString("identityScope").equals("imported-snapshot-not-live-verification"),"评论身份声明或核验范围无效");
      if(status.equals("verified")){String author=profile(text(c,"authorProfileUrl")),channel=profile(text(row,"profileUrl"));require(!author.isEmpty()&&!channel.isEmpty()&&author.equals(channel)&&method.equals("profile_url"),"备份作者主页不一致；拒绝伪造已核验身份");}
      if(status.equals("platform_marked"))require(method.equals("platform_label"),"缺少平台标注来源依据");
    }JSONObject coverage=row.getJSONObject("coverage");require(!coverage.optBoolean("complete")||(!coverage.optBoolean("hasMore")&&coverage.optInt("offset")==0&&(coverage.isNull("total")||coverage.optDouble("total")<=a.length())),"评论完整范围声明与分页数据矛盾");JSONObject body=SourceAnalysisPacket.copy(row);body.remove("id");body.remove("sourceKey");body.remove("recordRevision");String key=row.optString("sourceKey");require(key.matches("observation:[a-f0-9]{64}")&&row.optString("id").equals(key+":"+SourceAnalysisPacket.hash(canonical(body))),"完整评论快照哈希与身份不符，拒绝同ID替换原证据");}
    if(kind.equals("rules")||kind.equals("drafts")){for(String k:FIELDS){String s=text(row,k);int max=k.equals("title")||k.equals("timeframe")?120:k.equals("universe")||k.equals("signalTiming")?300:2000;require(s.length()<=max,"规则字段超出旧合同长度，未截断");}assess(row);}
    if(kind.equals("labels"))require(Arrays.asList("support","counter","question","unclassified").contains(row.optString("label")),"人工证据分类无效");SourceAnalysisPacket.size(row);return row;
  }
  static JSONObject commentRef(JSONObject obs,String id) throws Exception {JSONArray list=obs.getJSONArray("comments");for(int i=0;i<list.length();i++){JSONObject c=list.getJSONObject(i);if(c.optString("commentId").equals(id))return new JSONObject().put("bundleId",obs.getString("id")).put("commentId",id).put("snapshot",c);}throw new IllegalArgumentException("评论来源缺失；未关联同名新评论");}
  static JSONObject exactComment(JSONObject ref,JSONArray rows) throws Exception {for(int i=0;i<rows.length();i++){JSONObject o=rows.getJSONObject(i);if(!o.optString("id").equals(ref.optString("bundleId")))continue;validate(o);require(canonical(commentRef(o,ref.getString("commentId")).getJSONObject("snapshot")).equals(canonical(ref.getJSONObject("snapshot"))),"评论版本失配；拒绝错误来源跳转");return o;}throw new IllegalArgumentException("原评论快照缺失，原来源ID保留；不自动匹配新版本");}
  static JSONArray comments(JSONObject row,String query,String filter) throws Exception {
    JSONArray list=row.getJSONArray("comments"),out=new JSONArray();Map<String,JSONObject> byId=new HashMap<>();for(int i=0;i<list.length();i++)byId.put(list.getJSONObject(i).getString("commentId"),list.getJSONObject(i));
    for(int i=0;i<list.length();i++){JSONObject c=SourceAnalysisPacket.copy(list.getJSONObject(i));String status=c.optString("creatorStatus");boolean verified=status.equals("verified")||status.equals("platform_marked");if(filter.equals("creator")&&!verified||filter.equals("suspected")&&!status.equals("suspected"))continue;
      JSONObject parent=byId.get(c.optString("parentCommentId"));c.put("parentText",parent==null?"":parent.optString("text")).put("parentAuthorName",parent==null?"":parent.optString("authorName")).put("parentMissing",!c.optString("parentCommentId").isEmpty()&&parent==null);
      if((c.optString("text")+c.optString("authorName")+c.optString("parentText")).toLowerCase(Locale.ROOT).contains(query.toLowerCase(Locale.ROOT)))out.put(c);}
    return out;
  }
  static JSONObject bindSource(JSONObject obs,JSONArray collections,JSONArray docs) throws Exception {
    JSONArray matches=new JSONArray();String[] kinds={"collections","docs"};JSONArray[] groups={collections,docs};for(int g=0;g<2;g++)for(int i=0;i<groups[g].length();i++){JSONObject r=groups[g].getJSONObject(i);String url=SourceAnalysisPacket.publicUrl(r.optString("sourceUrl")),body=r.optString("text");if(url.isEmpty()||!url.equals(obs.optString("sourceUrl"))||body.isEmpty()||(!body.equals(obs.optString("content"))&&!body.equals(obs.optString("transcript"))))continue;
      JSONObject snap=SourceAnalysisPacket.snapshot(SourceAnalysisPacket.copy(r).put("sourceKind",kinds[g]));matches.put(new JSONObject().put("kind",kinds[g]).put("id",r.getString("id")).put("snapshot",snap).put("bodyHash",SourceAnalysisPacket.hash(body+'\0'+r.optString("originalText"))));}
    require(matches.length()==1,"未找到唯一且全文一致的本机原稿；请核对旧版本，未按URL或ID强行跳转");return matches.getJSONObject(0);
  }
  static JSONArray array(Object v) throws Exception {if(v instanceof JSONArray)return (JSONArray)v;if(v instanceof String){JSONTokener tokener=new JSONTokener((String)v);Object parsed=tokener.nextValue();require(parsed instanceof JSONArray&&tokener.nextClean()==0,"旧规则卡JSON不是数组或末尾含额外数据");return (JSONArray)parsed;}throw new IllegalArgumentException("导入列表不是数组");}
  static void commentDataValid(JSONObject o){require(!o.has("commentData")||o.isNull("commentData")||o.optJSONObject("commentData")!=null,"评论数据不是对象");}
  static JSONObject labelsObject(Object raw) throws Exception {if(raw instanceof JSONObject)return (JSONObject)raw;require(raw instanceof String,"旧分类记录不是对象");JSONTokener tokener=new JSONTokener((String)raw);Object parsed=tokener.nextValue();require(parsed instanceof JSONObject&&tokener.nextClean()==0,"旧分类JSON无效或含额外数据");return (JSONObject)parsed;}
  static JSONObject resolve(JSONArray rows,String channel,String obs,String comment) throws Exception {JSONArray matches=new JSONArray();for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);if(row.optString("kind").equals("observations")&&row.optString("channelId").equals(channel)&&row.optString("observationId").equals(obs)){try{matches.put(commentRef(row,comment));}catch(Exception ignored){}}}return matches.length()==1?matches.getJSONObject(0):new JSONObject();}
  static JSONArray normalize(String json) throws Exception {
    require(SourceAnalysisPacket.utf8Size(json)<=SourceAnalysisPacket.BYTE_LIMIT,"导入文件超过25MiB，未截断");JSONTokener tokener=new JSONTokener(json);Object parsed=tokener.nextValue();require(tokener.nextClean()==0,"JSON末尾含额外数据");JSONObject root=parsed instanceof JSONObject?(JSONObject)parsed:new JSONObject();JSONArray records=new JSONArray();
    if(root.optString("schema").equals("comment-workshop-v1")){JSONArray input=root.getJSONArray("records");require(input.length()<=10000,"工坊备份超过10000条");for(int i=0;i<input.length();i++){require(!input.getJSONObject(i).optString("kind").equals("previews"),"备份不接受未确认预览记录");records.put(validate(input.getJSONObject(i)));}return records;}
    JSONArray channels=null;
    if(parsed instanceof JSONArray)channels=(JSONArray)parsed;else if(root.optJSONArray("expertChannels")!=null)channels=root.getJSONArray("expertChannels");else if(obj(root,"data").optJSONArray("expertChannels")!=null)channels=obj(root,"data").getJSONArray("expertChannels");else if(root.optJSONArray("channels")!=null)channels=root.getJSONArray("channels");
    else if(root.optJSONObject("channel")!=null&&root.optJSONObject("observation")!=null){commentDataValid(root);records.put(observation(root.getJSONObject("channel"),root.getJSONObject("observation"),obj(root,"commentData")));}
    else require(root.has("webstock.commentStrategy.ruleCards")||root.has("webstock.commentStrategy.evidenceLabels"),"不是旧评论/规则卡导出或工坊备份");
    if(channels!=null)for(int i=0;i<channels.length();i++){JSONObject channel=channels.getJSONObject(i);JSONArray observations=channel.getJSONArray("observations");for(int j=0;j<observations.length();j++){JSONObject o=observations.getJSONObject(j);commentDataValid(o);records.put(observation(channel,o,obj(o,"commentData")));}}
    if(root.has("webstock.commentStrategy.ruleCards")){JSONArray cards=array(root.get("webstock.commentStrategy.ruleCards"));for(int i=0;i<cards.length();i++){JSONObject card=SourceAnalysisPacket.copy(cards.getJSONObject(i));require(card.opt("id") instanceof String&&!card.optString("id").isEmpty(),"旧规则卡缺少ID");card.put("kind","rules").put("sourceRef",resolve(records,id(card.opt("sourceChannelId")),id(card.opt("sourceObservationId")),text(card,"sourceCommentId"))).put("provenance","manual-legacy-unvalidated");records.put(validate(card));}}
    if(root.has("webstock.commentStrategy.evidenceLabels")){JSONObject labels=labelsObject(root.get("webstock.commentStrategy.evidenceLabels"));Iterator<String> it=labels.keys();while(it.hasNext()){String key=it.next();int a=key.indexOf(':'),b=key.indexOf(':',a+1);require(a>0&&b>a,"旧证据分类键无效");JSONObject ref=resolve(records,key.substring(0,a),key.substring(a+1,b),key.substring(b+1));records.put(validate(new JSONObject().put("kind","labels").put("id",ref.length()==0?"legacy-label:"+SourceAnalysisPacket.hash(key):labelId(ref.getString("bundleId"),ref.getString("commentId"))).put("label",labels.get(key)).put("sourceRef",ref).put("legacyKey",key).put("provenance","manual-legacy-unvalidated")));}}
    require(records.length()<=10000,"导入超过10000条工坊记录");return records;
  }
}
